test("redirects the legacy workspace to the canonical product without legacy API calls", async ({
  page,
}) => {
  const requestedPaths: string[] = [];
  page.on("request", (request) => requestedPaths.push(new URL(request.url()).pathname));

  await page.goto("/workspace?source=legacy#proof");

  await expect(page).toHaveURL("http://127.0.0.1:4173/");
  await expect(
    page.getByRole("heading", { name: /both renders succeeded.*look different/iu }),
  ).toBeVisible();
  await expect(
    page.getByText(/ColorTrace traces successful-but-wrong color across checksum-pinned/iu),
  ).toBeVisible();
  expect(requestedPaths.some((path) => path.startsWith("/v1/session"))).toBe(false);
  expect(requestedPaths.some((path) => path.startsWith("/v1/incidents"))).toBe(false);
});

test("completes the visual-first recovery flow with exact bound approval", async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  const { mutations } = await installDemoApi(page);
  const requestUrls: string[] = [];
  page.on("request", (request) => requestUrls.push(request.url()));
  await page.goto("/");

  await expect(
    page.getByRole("heading", { name: /both renders succeeded.*look different/iu }),
  ).toBeVisible();
  const firstFold = page.locator('[data-first-fold="comparison-and-action"]');
  const openFilmAction = page.getByRole("link", { name: "Explore the open-film proof" });
  const compatibilityDisclosure = page.getByText(COMPATIBILITY_DISCLOSURE_LABEL, { exact: true });
  const compatibilityLabel = page.getByText("Secondary compatibility workflow", {
    exact: true,
  });
  const openFilmExpected = firstFold.getByAltText(/Expected state open-film pixel preview/iu);
  const openFilmObserved = firstFold.getByAltText(/Observed failure open-film pixel preview/iu);
  const syntheticExpected = page.getByAltText(/Expected cinematic soundstage portrait/u);
  await expect(openFilmExpected).toHaveJSProperty("naturalWidth", 960);
  await expect(openFilmObserved).toHaveJSProperty("naturalWidth", 960);
  await expect(firstFold.getByText("PNG hash verified · pixel evidence")).toHaveCount(2);
  await expect(syntheticExpected).toHaveJSProperty("naturalWidth", 160);
  const callToAction = page
    .locator(".shot-landing__legacy-action button")
    .filter({ hasText: "Investigate the color fault" });
  await expect(openFilmAction).toHaveAttribute("href", "#reference-suite-title");
  await expect(compatibilityDisclosure).toBeVisible();
  await expect(compatibilityLabel).toBeHidden();
  await expect(syntheticExpected).toBeHidden();
  await expect(callToAction).toBeHidden();
  expect(
    await syntheticExpected.evaluate(
      (element) => element.closest('[data-first-fold="comparison-and-action"]') === null,
    ),
  ).toBe(true);
  expect(
    await callToAction.evaluate(
      (element) => element.closest('[data-first-fold="comparison-and-action"]') === null,
    ),
  ).toBe(true);
  for (const locator of [firstFold, openFilmAction, openFilmExpected, openFilmObserved]) {
    const box = await locator.boundingBox();
    expect(box).not.toBeNull();
    expect((box?.y ?? 901) + (box?.height ?? 0)).toBeLessThanOrEqual(900);
  }
  expect(requestUrls.filter((url) => new URL(url).pathname.startsWith("/v1/demo/runs"))).toEqual(
    [],
  );
  const previewAccessibility = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
    .analyze();
  expect(previewAccessibility.violations).toEqual([]);
  if (process.env.COLORTRACE_CAPTURE_SHOT_SAFE_SCREENSHOT === "1") {
    await page.screenshot({
      animations: "disabled",
      path: "../../.cache/playwright/shot-safe-preview-1440x900.png",
    });
  }
  await compatibilityDisclosure.click();
  await expect(compatibilityLabel).toBeVisible();
  await expect(syntheticExpected).toBeVisible();
  await expect(callToAction).toBeVisible();
  const syntheticBox = await syntheticExpected.boundingBox();
  expect(syntheticBox).not.toBeNull();
  expect(syntheticBox?.y ?? 0).toBeGreaterThanOrEqual(900);
  await page.getByRole("button", { name: "Investigate the color fault" }).click();

  await expect(page.getByRole("heading", { name: "Expected versus observed" })).toBeFocused();
  const expectedVisual = page.getByAltText("Declared expected output");
  const observedVisual = page.getByAltText(/Observed output with a visible color shift/u);
  const diffVisual = page.getByAltText(
    "Illustrative pixel difference between expected and observed output",
  );
  await expect(expectedVisual).toBeVisible();
  await expect(observedVisual).toBeVisible();
  await expect(expectedVisual).toHaveJSProperty("naturalWidth", 160);
  await expect(observedVisual).toHaveJSProperty("naturalWidth", 160);
  await expect(diffVisual).toHaveJSProperty("naturalWidth", 160);
  await expect(
    page.getByRole("heading", { name: "Same configuration, different resolved LUT" }),
  ).toBeVisible();
  const facts = page.getByLabel("Investigation facts");
  await expect(facts).toContainText("2 succeeded");
  await expect(facts).toContainText("Same");
  await expect(facts).toContainText("Different");
  await expect(facts).toContainText("4 outputs");
  await expect(facts).toContainText("3 outputs");
  const factsBox = await facts.boundingBox();
  expect(factsBox).not.toBeNull();
  expect(factsBox?.y ?? -1).toBeGreaterThanOrEqual(0);
  expect((factsBox?.y ?? 901) + (factsBox?.height ?? 0)).toBeLessThanOrEqual(900);
  const impact = page.getByLabel("Synthetic fixture impact comparison");
  await expect(impact).toContainText("3 affected source frames targeted");
  await expect(impact).toContainText("3 verified-safe source frames excluded");
  await expect(impact).toContainText(
    "3 fewer source-frame rerenders than rerendering all 6 observed source frames",
  );
  await expect(impact).toContainText("Synthetic fixture comparison—not a production benchmark");
  await expect(impact).toContainText("Time, compute, and cost savings were not measured");
  const impactBox = await impact.boundingBox();
  expect(impactBox).not.toBeNull();
  expect((impactBox?.y ?? 901) + (impactBox?.height ?? 0)).toBeLessThanOrEqual(900);
  await expect(page.getByText("Root cause confirmed")).toBeVisible();
  await expect(page.getByText("Declared configuration ruled out")).toBeVisible();
  await expect(page.getByText("Worker-only explanation rejected")).toBeVisible();
  await expect(page.getByText("Unrelated event ruled out")).toBeVisible();
  await expect(page.getByText("3 bounded Grafana reads", { exact: true })).toBeVisible();
  await expect(page.getByText("4 current evidence views", { exact: true })).toBeVisible();
  await expect(page.getByText("Untrusted", { exact: true })).toBeVisible();
  await expect(
    page.getByText("Deterministic validator · decision authority", { exact: true }),
  ).toBeVisible();
  const activity = page.getByRole("region", { name: "What actually happened" });
  await expect(activity.getByText("Inspect 2 recorded events", { exact: true })).toBeVisible();
  await expect(activity.getByText("Run created", { exact: true })).toBeHidden();
  await expect(page.getByText("3 of 7 outputs protected (43%).", { exact: true })).toBeVisible();
  await expect(page.getByText("Inspect 5 bounded commands", { exact: true })).toBeVisible();
  await expect(page.locator(".shot-plan-review .shot-command")).toHaveCount(5);
  await expect(page.locator(".shot-plan-review .shot-command").first()).toBeHidden();
  await page.getByText("Inspect 5 bounded commands", { exact: true }).click();
  await expect(page.locator(".shot-plan-review .shot-command").first()).toBeVisible();
  expect(await page.locator("main").innerText()).not.toContain("sha256:");
  await expect(page.getByText(PLAN_DIGEST, { exact: true }).first()).toBeHidden();

  const accessibility = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
    .analyze();
  expect(accessibility.violations).toEqual([]);
  if (process.env.COLORTRACE_CAPTURE_SHOT_SAFE_SCREENSHOT === "1") {
    await page.screenshot({
      animations: "disabled",
      path: "../../.cache/playwright/shot-safe-1440x900.png",
    });
  }

  const approve = page.getByRole("button", { name: "Approve recovery action" });
  await expect(approve).toBeDisabled();
  await page.getByLabel("Retype review nonce").fill(NONCE);
  await page.getByLabel("Type approval phrase").fill("APPROVE_COLORTRACE_SIMULATOR_ACTION");
  await page
    .getByLabel(/I approve only the displayed targets and keep the exclusions protected/u)
    .check();
  await expect(approve).toBeEnabled();
  await approve.click();

  await expect(page.getByAltText("Recovered output")).toBeVisible();
  expect(
    await page.evaluate(() => ({
      nonce: sessionStorage.getItem("colortrace.demo.approval-nonce"),
      run: sessionStorage.getItem("colortrace.demo.run-id"),
    })),
  ).toEqual({ nonce: null, run: RUN_ID });
  await expect(page.locator("body")).not.toContainText(NONCE);
  await expect(
    page
      .getByRole("region", { name: "Recovered output", exact: true })
      .getByText("Recovered all 4 affected outputs; all 3 protected outputs remained unchanged.", {
        exact: true,
      }),
  ).toBeVisible();
  const outcome = page.getByLabel("Recovery outcome");
  await expect(outcome).toContainText("4 outputs");
  await expect(outcome).toContainText("3 unchanged");
  await expect(outcome).toContainText("7/7 passed");
  await expect(outcome).toContainText("Ready for human closure");
  await page.getByLabel(/I verified the recovered image/u).check();
  await page.getByRole("button", { name: "Verify and close recovery" }).click();

  await expect(page.getByRole("heading", { name: /verified receipt/u })).toBeVisible();
  await expect(page.getByText("Recorded and verified", { exact: true })).toBeVisible();
  await page.getByText("Technical proof and provenance", { exact: true }).click();
  const technicalProof = page.locator(".shot-technical");
  await expect(
    technicalProof.getByText("log.correlated-events", { exact: true }).first(),
  ).toBeVisible();
  await expect(technicalProof.getByText("query_loki_logs", { exact: true }).first()).toBeVisible();
  await expect(
    technicalProof.getByText("post-action-telemetry-correlation", { exact: true }).first(),
  ).toBeVisible();
  await expect(technicalProof.getByText(PLAN_DIGEST, { exact: true }).first()).toBeVisible();
  expect(
    await page.evaluate(() => ({
      nonce: sessionStorage.getItem("colortrace.demo.approval-nonce"),
      run: sessionStorage.getItem("colortrace.demo.run-id"),
    })),
  ).toEqual({ nonce: null, run: RUN_ID });

  expect(mutations).toHaveLength(3);
  expect(mutations[0]).toMatchObject({
    schema: "colortrace-demo-run-request/v2",
    approval_nonce: NONCE,
    idempotency_key: expect.stringMatching(/^demo-start-/u),
  });
  expect(mutations[1]).toMatchObject({
    approval_nonce: NONCE,
    approval_phrase: "APPROVE_COLORTRACE_SIMULATOR_ACTION",
    expected_plan_sha256: PLAN_DIGEST,
    expected_target_sha256: TARGET_DIGEST,
  });
  expect(mutations[2]).toMatchObject({
    expected_packet_sha256: PACKET_DIGEST,
    expected_outcome_sha256: OUTCOME_DIGEST,
  });
  expect(mutations.filter((request) => JSON.stringify(request).includes(NONCE))).toHaveLength(2);
  expect(requestUrls.every((url) => !url.includes(NONCE))).toBe(true);
});

test("keeps the clean-session flow usable on a small reduced-motion viewport", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await installDemoApi(page);
  await page.goto("/");

  await page.keyboard.press("Tab");
  await expect(page.getByRole("link", { name: "Skip to recovery workspace" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("link", { name: "ColorTrace home" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("link", { name: "Explore the open-film proof" })).toBeFocused();
  const mobileFirstFold = page.locator('[data-first-fold="comparison-and-action"]');
  const mobileHook = page.getByRole("heading", {
    name: /both renders succeeded.*look different/iu,
  });
  const mobileOpenFilmAction = page.getByRole("link", { name: "Explore the open-film proof" });
  const mobileCallToAction = page
    .locator(".shot-landing__legacy-action button")
    .filter({ hasText: "Investigate the color fault" });
  const mobileExpected = mobileFirstFold.getByAltText(/Expected state open-film pixel preview/iu);
  const mobileObserved = mobileFirstFold.getByAltText(/Observed failure open-film pixel preview/iu);
  const mobileSyntheticExpected = page.getByAltText(/Expected cinematic soundstage portrait/u);
  await expect(mobileExpected).toHaveJSProperty("naturalWidth", 960);
  await expect(mobileObserved).toHaveJSProperty("naturalWidth", 960);
  await expect(mobileSyntheticExpected).toHaveJSProperty("naturalWidth", 160);
  await expect(mobileSyntheticExpected).toBeHidden();
  await expect(mobileCallToAction).toBeHidden();
  expect(
    await mobileSyntheticExpected.evaluate(
      (element) => element.closest('[data-first-fold="comparison-and-action"]') === null,
    ),
  ).toBe(true);
  expect(
    await mobileCallToAction.evaluate(
      (element) => element.closest('[data-first-fold="comparison-and-action"]') === null,
    ),
  ).toBe(true);
  for (const locator of [
    mobileFirstFold,
    mobileHook,
    mobileOpenFilmAction,
    mobileExpected,
    mobileObserved,
  ]) {
    const box = await locator.boundingBox();
    expect(box).not.toBeNull();
    expect((box?.y ?? 845) + (box?.height ?? 0)).toBeLessThanOrEqual(844);
  }
  if (process.env.COLORTRACE_CAPTURE_SHOT_SAFE_SCREENSHOT === "1") {
    await page.screenshot({
      animations: "disabled",
      path: "../../.cache/playwright/shot-safe-preview-390x844.png",
    });
  }
  await openCompatibilityWorkflow(page);
  await expect(mobileSyntheticExpected).toBeVisible();
  await expect(mobileCallToAction).toBeVisible();
  const mobileSyntheticBox = await mobileSyntheticExpected.boundingBox();
  expect(mobileSyntheticBox).not.toBeNull();
  expect(mobileSyntheticBox?.y ?? 0).toBeGreaterThanOrEqual(844);
  await mobileCallToAction.click();
  await expect(page.getByRole("heading", { name: "Expected versus observed" })).toBeFocused();
  const expectedVisual = page.getByAltText("Declared expected output");
  const observedVisual = page.getByAltText(/Observed output with a visible color shift/u);
  await expect(expectedVisual).toBeVisible();
  await expect(expectedVisual).toHaveJSProperty("naturalWidth", 160);
  await expect(observedVisual).toHaveJSProperty("naturalWidth", 160);
  await expect(page.getByLabel("Investigation facts")).toBeVisible();
  await expect(page.getByLabel("Synthetic fixture impact comparison")).toContainText(
    "3 fewer source-frame rerenders than rerendering all 6 observed source frames",
  );
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(
    true,
  );
  expect(
    await page.locator(".shot-app").evaluate((element) => getComputedStyle(element).animationName),
  ).toBe("none");
  const accessibility = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
    .analyze();
  expect(accessibility.violations).toEqual([]);
  if (process.env.COLORTRACE_CAPTURE_SHOT_SAFE_SCREENSHOT === "1") {
    await page.screenshot({
      animations: "disabled",
      path: "../../.cache/playwright/shot-safe-390x844.png",
    });
  }
});

test("replays the persisted start request after response loss and reload", async ({ page }) => {
  const { mutationBodies, mutations } = await installDemoApi(page, {
    ambiguousStartOnce: true,
  });
  await page.goto("/");

  await openCompatibilityWorkflow(page);
  await page.getByRole("button", { name: "Investigate the color fault" }).click();
  await expect(page.getByText(/The recovery service is unavailable/iu)).toBeVisible();
  const pending = await page.evaluate(() => ({
    nonce: sessionStorage.getItem("colortrace.demo.approval-nonce"),
    startKey: sessionStorage.getItem("colortrace.demo.start-idempotency-key"),
  }));
  expect(pending.nonce).toBe(NONCE);
  expect(pending.startKey).toMatch(/^demo-start-/u);

  await page.reload();

  await expect(page.getByRole("heading", { name: "Expected versus observed" })).toBeVisible();
  expect(mutations.length).toBeGreaterThanOrEqual(2);
  expect(mutations.length).toBeLessThanOrEqual(3);
  expect(mutationBodies.every((body) => body === mutationBodies[0])).toBe(true);
  expect(
    mutations.every(
      (mutation) =>
        (mutation as { readonly idempotency_key?: unknown }).idempotency_key === pending.startKey,
    ),
  ).toBe(true);
  expect(
    await page.evaluate(() => ({
      run: sessionStorage.getItem("colortrace.demo.run-id"),
      startKey: sessionStorage.getItem("colortrace.demo.start-idempotency-key"),
    })),
  ).toEqual({ run: RUN_ID, startKey: null });
});

test("replays the persisted reset after response loss and reload", async ({ page }) => {
  const { mutationBodies, mutations } = await installDemoApi(page, {
    ambiguousResetOnce: true,
    initialState: "closed",
  });
  await page.goto("/");
  await page.evaluate((runId) => sessionStorage.setItem("colortrace.demo.run-id", runId), RUN_ID);
  await page.reload();

  await expect(page.getByRole("heading", { name: /verified receipt/u })).toBeVisible();
  await page.getByRole("button", { name: "Reset for another run" }).click();
  await expect(page.getByRole("alert")).toContainText("result is uncertain");
  const pending = await page.evaluate(() => ({
    run: sessionStorage.getItem("colortrace.demo.run-id"),
    resetKey: sessionStorage.getItem("colortrace.demo.reset-idempotency-key"),
  }));
  expect(pending.run).toBe(RUN_ID);
  expect(pending.resetKey).toMatch(/^demo-reset-/u);

  await page.reload();

  await openCompatibilityWorkflow(page);
  await expect(page.getByText(/reset to authored generation 1/u)).toBeVisible();
  expect(mutations.length).toBeGreaterThanOrEqual(2);
  expect(mutations.length).toBeLessThanOrEqual(3);
  expect(mutationBodies.every((body) => body === mutationBodies[0])).toBe(true);
  expect(
    mutations.every(
      (mutation) =>
        (mutation as { readonly idempotency_key?: unknown }).idempotency_key === pending.resetKey,
    ),
  ).toBe(true);
  expect(await page.evaluate(() => sessionStorage.length)).toBe(0);
});

test("recovers an active conflict without inheriting an approval nonce", async ({ page }) => {
  await installDemoApi(page, { startConflict: "demo-active-run-exists" });
  await page.goto("/");

  await openCompatibilityWorkflow(page);
  await page.getByRole("button", { name: "Investigate the color fault" }).click();

  await expect(
    page.getByRole("heading", { name: "Review cannot continue in this browser" }),
  ).toBeVisible();
  expect(
    await page.evaluate(() => ({
      nonce: sessionStorage.getItem("colortrace.demo.approval-nonce"),
      run: sessionStorage.getItem("colortrace.demo.run-id"),
    })),
  ).toEqual({ nonce: null, run: RUN_ID });
  await expect(page.getByRole("button", { name: "Approve recovery action" })).toHaveCount(0);
});

test("recovers a reset-required conflict to its terminal receipt", async ({ page }) => {
  await installDemoApi(page, {
    initialState: "closed",
    startConflict: "demo-reset-required",
  });
  await page.goto("/");

  await openCompatibilityWorkflow(page);
  await page.getByRole("button", { name: "Investigate the color fault" }).click();

  await expect(page.getByRole("heading", { name: /verified receipt/u })).toBeVisible();
  await expect(page.getByRole("button", { name: "Reset for another run" })).toBeEnabled();
  expect(await page.evaluate(() => sessionStorage.getItem("colortrace.demo.run-id"))).toBe(RUN_ID);
});

test("resumes with the session nonce without leaking or reusing it", async ({ page }) => {
  const { mutations } = await installDemoApi(page);
  await page.goto("/");
  await openCompatibilityWorkflow(page);
  await page.getByRole("button", { name: "Investigate the color fault" }).click();

  expect(await page.evaluate(() => sessionStorage.getItem("colortrace.demo.approval-nonce"))).toBe(
    NONCE,
  );
  await page.reload();
  await expect(page.getByRole("heading", { name: "Decide the exact plan" })).toBeVisible();

  await page.getByLabel("Retype review nonce").fill(NONCE);
  await page.getByLabel("Type approval phrase").fill("APPROVE_COLORTRACE_SIMULATOR_ACTION");
  await page
    .getByLabel(/I approve only the displayed targets and keep the exclusions protected/u)
    .check();
  await page.getByRole("button", { name: "Approve recovery action" }).click();

  await expect(page.getByRole("heading", { name: "Recovered output", exact: true })).toBeVisible();
  expect(
    await page.evaluate(() => sessionStorage.getItem("colortrace.demo.approval-nonce")),
  ).toBeNull();
  await page.reload();
  await expect(page.getByRole("heading", { name: "Recovered output", exact: true })).toBeVisible();
  await expect(page.getByRole("button", { name: "Approve recovery action" })).toHaveCount(0);
  expect(mutations.filter((request) => JSON.stringify(request).includes(NONCE))).toHaveLength(2);
});
